const client = mqtt.connect('mqtt://broker', { clientId: 'billing-ledger', clean: false })
client.on('connect', (connack) => {
  if (!connack.sessionPresent) console.warn('session lost')
  client.subscribe('orders/#', { qos: 1 }, (err) => { if (err) throw err })
})
